-- Vollständiger Laborwerte-Katalog: 12 Kategorien, 34 Unterkategorien, 136 Parameter.
-- Auto-generiert aus laborwerte_katalog.xlsx + Anreicherung (Referenzbereiche, Kurztexte,
-- result_type). Referenzbereiche tragen seit 2026-07 pro Zeile eine `source`-Spalte
-- (siehe Migration 0013): recherchierte Quellen, bevorzugt DACH-Laborhandbücher
-- (Uniklinikum Ulm, Uniklinikum Münster) und Herstellerpackungsbeilagen (Roche Elecsys),
-- sonst internationale Referenzen (NBME, Mayo Clinic, NIH ODS u. a.). Einige Werte sind
-- weiterhin bewusst grobe Orientierung ohne einzelne Institutsquelle (z. B. Differential-
-- blutbild-Prozente, Hauttests) -- das ist im jeweiligen `source`-Feld vermerkt.
-- learn_more_url zeigt weiterhin auf eine austauschbare Platzhalter-Domain.

truncate table lab_results, lab_reference_ranges, lab_parameters, lab_subcategories, lab_categories, organ_lab_subcategories cascade;

