insert into lab_parameters (subcategory_id, key, name, abbreviation, unit, description_level1, description_level2, description_level3, learn_more_url, result_type, sort_order) values
  ((select id from lab_subcategories where key = 'small_blood_count'), 'erythrocytes', 'Erythrozyten', null, 'Mio/µl', 'Rote Blutzellen bringen Sauerstoff von der Lunge zu deinem ganzen Körper.', 'Rote Blutkörperchen; Transport von Sauerstoff im Blut.', 'Zelluläres Kompartiment des Sauerstofftransports; Anzahl variiert mit Höhe, Hydratationsstatus und Erythropoetin-Aktivität, wird gemeinsam mit Hb/Hkt/Indizes zur Anämie-Klassifikation (mikro-/normo-/makrozytär) herangezogen.', 'https://platzhalter-lexikon.example/erythrocytes', 'numeric', 1),
  ((select id from lab_subcategories where key = 'small_blood_count'), 'hemoglobin', 'Hämoglobin', 'Hb', 'g/dl', 'Hämoglobin ist der rote Farbstoff im Blut, der den Sauerstoff festhält und transportiert.', 'Sauerstofftransportprotein der roten Blutkörperchen; zentraler Marker für Anämie.', 'Eisenhaltiges Transportprotein in Erythrozyten; zentraler Parameter der Anämiediagnostik, interpretiert gemeinsam mit MCV/MCH zur Ursachenabklärung (z. B. Eisen-, Vitamin-B12-Mangel, chronische Erkrankung).', 'https://platzhalter-lexikon.example/hemoglobin', 'numeric', 2),
  ((select id from lab_subcategories where key = 'small_blood_count'), 'hematocrit', 'Hämatokrit', 'Hkt', '%', 'Zeigt, wie viel Prozent deines Blutes aus roten Blutzellen besteht.', 'Anteil der roten Blutkörperchen am Gesamtblutvolumen.', 'Volumenanteil der zellulären Blutbestandteile am Gesamtblutvolumen; eng korreliert mit Hb, zusätzlich beeinflusst durch das Plasmavolumen (z. B. Dehydratation, Schwangerschaft).', 'https://platzhalter-lexikon.example/hematocrit', 'numeric', 3),
  ((select id from lab_subcategories where key = 'small_blood_count'), 'mcv', 'Mittleres korpuskuläres Volumen', 'MCV', 'fl', 'Verrät, ob deine roten Blutzellen eher klein, normal oder groß sind.', 'Mittleres Volumen eines einzelnen roten Blutkörperchens; hilft bei der Anämie-Einordnung.', 'Mittleres Erythrozytenvolumen; Leitparameter zur morphologischen Anämie-Einteilung (mikro-, normo-, makrozytär), z. B. mikrozytär bei Eisenmangel, makrozytär bei B12-/Folsäuremangel.', 'https://platzhalter-lexikon.example/mcv', 'numeric', 4),
  ((select id from lab_subcategories where key = 'small_blood_count'), 'mch', 'Mittleres korpuskuläres Hämoglobin', 'MCH', 'pg', 'Zeigt, wie viel roter Blutfarbstoff im Durchschnitt in einer einzelnen Blutzelle steckt.', 'Mittlerer Hämoglobingehalt eines einzelnen roten Blutkörperchens.', 'Mittlerer Hämoglobingehalt pro Erythrozyt; korreliert meist mit dem MCV, ergänzt die morphologische Anämie-Differenzierung.', 'https://platzhalter-lexikon.example/mch', 'numeric', 5),
  ((select id from lab_subcategories where key = 'small_blood_count'), 'mchc', 'Mittlere korpuskuläre Hb-Konzentration', 'MCHC', 'g/dl', 'Sagt aus, wie konzentriert der rote Blutfarbstoff in den Blutzellen ist.', 'Mittlere Hämoglobinkonzentration in den roten Blutkörperchen.', 'Hämoglobinkonzentration bezogen auf das Erythrozytenvolumen; erniedrigt v. a. bei hypochromen Anämien (z. B. Eisenmangel, Thalassämie).', 'https://platzhalter-lexikon.example/mchc', 'numeric', 6),
  ((select id from lab_subcategories where key = 'small_blood_count'), 'rdw', 'Erythrozyten-Verteilungsbreite', 'RDW', '%', 'Zeigt, wie unterschiedlich groß deine roten Blutzellen zueinander sind.', 'Größenverteilungsbreite der roten Blutkörperchen; erhöht bei manchen Anämieformen.', 'Streuungsmaß der Erythrozytengröße (Anisozytose); erhöht u. a. bei beginnendem Eisen-, Folsäure- oder B12-Mangel, hilfreich zur Abgrenzung gemischter Anämieformen.', 'https://platzhalter-lexikon.example/rdw', 'numeric', 7),
  ((select id from lab_subcategories where key = 'small_blood_count'), 'leukocytes', 'Leukozyten', null, 'Tsd/µl', 'Weiße Blutzellen sind die Abwehrzellen deines Körpers gegen Krankheitserreger.', 'Weiße Blutkörperchen; erhöht bei Infektionen und Entzündungen.', 'Gesamtzahl der Leukozyten als Summe aller Subpopulationen; Erhöhung (Leukozytose) bzw. Erniedrigung (Leukopenie) erfordert ein Differenzialblutbild zur weiteren Einordnung.', 'https://platzhalter-lexikon.example/leukocytes', 'numeric', 8),
  ((select id from lab_subcategories where key = 'small_blood_count'), 'platelets', 'Thrombozyten', null, 'Tsd/µl', 'Blutplättchen sorgen dafür, dass eine Wunde aufhört zu bluten.', 'Blutplättchen; zentral für die Blutgerinnung.', 'Thrombozytenzahl; zentral für die primäre Hämostase, Interpretation im Kontext von Blutungsneigung (Thrombozytopenie) oder Thromboserisiko (Thrombozytose).', 'https://platzhalter-lexikon.example/platelets', 'numeric', 9),
  ((select id from lab_subcategories where key = 'small_blood_count'), 'mpv', 'Mittleres Thrombozytenvolumen', 'MPV', 'fl', 'Zeigt die durchschnittliche Größe deiner Blutplättchen.', 'Mittleres Volumen der Blutplättchen; Hinweis auf deren Umsatz.', 'Mittleres Thrombozytenvolumen; erhöht bei gesteigertem Thrombozytenumsatz (jüngere, größere Plättchen), ergänzt die Thrombozytenzahl bei der Ursachenabklärung von Thrombozytopenien.', 'https://platzhalter-lexikon.example/mpv', 'numeric', 10),
  ((select id from lab_subcategories where key = 'differential_blood_count'), 'neutrophils', 'Neutrophile Granulozyten', null, '%', 'Die häufigste Abwehrzelle, sie kämpft vor allem gegen Bakterien.', 'Häufigste weiße Blutkörperchen-Untergruppe; erste Abwehr gegen bakterielle Infektionen.', 'Größte Granulozyten-Subpopulation; Anstieg typisch bei bakteriellen Infekten und Stressreaktionen, Abfall (Neutropenie) erhöht das Infektionsrisiko.', 'https://platzhalter-lexikon.example/neutrophils', 'numeric', 1),
  ((select id from lab_subcategories where key = 'differential_blood_count'), 'lymphocytes', 'Lymphozyten', null, '%', 'Abwehrzellen, die besonders gegen Viren helfen und sich an Erreger "erinnern".', 'Weiße Blutkörperchen-Untergruppe, zentral für die Immunabwehr gegen Viren.', 'Umfasst T-, B- und NK-Zellen; relative/absolute Lymphozytose typisch bei viralen Infekten, Lymphopenie u. a. bei Immunsuppression oder schweren Akutinfekten.', 'https://platzhalter-lexikon.example/lymphocytes', 'numeric', 2),
  ((select id from lab_subcategories where key = 'differential_blood_count'), 'monocytes', 'Monozyten', null, '%', 'Aufräumzellen, die kranke Zellen und Erregerreste beseitigen.', 'Weiße Blutkörperchen-Untergruppe; räumen Krankheitserreger und Zelltrümmer ab.', 'Vorläufer der Gewebemakrophagen; Erhöhung bei chronischen Entzündungen, bestimmten Infektionen (z. B. Tuberkulose) und in der Erholungsphase nach Neutropenie.', 'https://platzhalter-lexikon.example/monocytes', 'numeric', 3),
  ((select id from lab_subcategories where key = 'differential_blood_count'), 'eosinophils', 'Eosinophile Granulozyten', null, '%', 'Diese Zellen sind besonders aktiv bei Allergien und Parasiten.', 'Weiße Blutkörperchen-Untergruppe; erhöht bei Allergien und Parasitenbefall.', 'Assoziiert mit Typ-2-Immunantworten; Eosinophilie typisch bei Allergien, Asthma, Parasitosen und bestimmten Medikamentenreaktionen.', 'https://platzhalter-lexikon.example/eosinophils', 'numeric', 4),
  ((select id from lab_subcategories where key = 'differential_blood_count'), 'basophils', 'Basophile Granulozyten', null, '%', 'Die seltenste Abwehrzellart, beteiligt an allergischen Reaktionen.', 'Seltenste weiße Blutkörperchen-Untergruppe; an allergischen Reaktionen beteiligt.', 'Enthalten histaminhaltige Granula; Beteiligung an IgE-vermittelten Reaktionen, selten isoliert erhöht (z. B. bei myeloproliferativen Erkrankungen).', 'https://platzhalter-lexikon.example/basophils', 'numeric', 5),
  ((select id from lab_subcategories where key = 'coagulation'), 'quick_inr', 'Quick-Wert / INR', null, '%', 'Zeigt, wie schnell dein Blut gerinnen kann, wenn eine Wunde entsteht.', 'Quick-Wert (bzw. INR ~0,9–1,1); prüft den äußeren Teil der Blutgerinnung, u. a. relevant bei Gerinnungshemmern.', 'Prüft den extrinsischen Gerinnungsweg (Faktoren II, V, VII, X); die INR standardisiert die Messung v. a. zur Steuerung einer Vitamin-K-Antagonisten-Therapie.', 'https://platzhalter-lexikon.example/quick-inr', 'numeric', 1),
  ((select id from lab_subcategories where key = 'coagulation'), 'ptt', 'Partielle Thromboplastinzeit', 'PTT', 'sek', 'Ein weiterer Test dafür, wie gut dein Blut gerinnt.', 'Partielle Thromboplastinzeit; prüft den inneren Teil der Blutgerinnung.', 'Prüft den intrinsischen und gemeinsamen Gerinnungsweg; verlängert bei Faktorenmangel, Hemmkörpern oder unter Heparintherapie.', 'https://platzhalter-lexikon.example/ptt', 'numeric', 2),
  ((select id from lab_subcategories where key = 'coagulation'), 'fibrinogen', 'Fibrinogen', null, 'mg/dl', 'Ein Eiweiß im Blut, das für die Wundheilung wichtig ist und bei Entzündungen ansteigt.', 'Gerinnungsfaktor und Akute-Phase-Protein; erhöht bei Entzündungen.', 'Akute-Phase-Protein und Vorstufe von Fibrin; erhöht bei Entzündung/Infektion, erniedrigt bei Verbrauchskoagulopathie (z. B. DIC) oder Leberfunktionsstörung.', 'https://platzhalter-lexikon.example/fibrinogen', 'numeric', 3),
  ((select id from lab_subcategories where key = 'coagulation'), 'd_dimer', 'D-Dimere', null, 'µg/l', 'Zeigt an, ob sich im Körper kürzlich ein Blutgerinnsel aufgelöst hat.', 'Abbauprodukt von Blutgerinnseln; Hinweis auf Thrombosen oder Embolien.', 'Fibrin-Spaltprodukt; hohe Sensitivität, aber geringe Spezifität für Thrombose/Embolie – v. a. zum Ausschluss bei niedriger klinischer Wahrscheinlichkeit geeignet.', 'https://platzhalter-lexikon.example/d-dimer', 'numeric', 4),
  ((select id from lab_subcategories where key = 'liver'), 'got_ast', 'GOT (AST)', null, 'U/l', 'Ein Eiweiß, das ins Blut gelangt, wenn Leber- oder Muskelzellen beschädigt sind.', 'Leberenzym (AST); erhöht bei Leber- oder Muskelzellschäden.', 'Mitochondriales/zytoplasmatisches Enzym, nicht leberspezifisch (auch Herz-/Skelettmuskel); Beurteilung meist im Verhältnis zu ALT (De-Ritis-Quotient).', 'https://platzhalter-lexikon.example/got-ast', 'numeric', 1),
  ((select id from lab_subcategories where key = 'liver'), 'gpt_alt', 'GPT (ALT)', null, 'U/l', 'Ein Leber-Eiweiß, das ansteigt, wenn Leberzellen gestresst oder verletzt sind.', 'Leberenzym (ALT); spezifischer Marker für Leberzellschäden.', 'Überwiegend zytoplasmatisches, leberspezifischeres Enzym als AST; sensitiver Marker für Hepatozytenschädigung, z. B. bei Fettleber, Virushepatitis oder Medikamententoxizität.', 'https://platzhalter-lexikon.example/gpt-alt', 'numeric', 2),
  ((select id from lab_subcategories where key = 'liver'), 'ggt', 'Gamma-GT', null, 'U/l', 'Ein Leberwert, der oft ansteigt bei Problemen mit der Galle oder durch Alkohol.', 'Leberenzym; empfindlicher Marker für Gallenstau und Alkoholeinfluss.', 'Membranständiges Enzym der Gallengangsepithelien und Hepatozyten; empfindlicher, aber unspezifischer Marker für Cholestase, Alkoholkonsum und Enzyminduktion durch Medikamente.', 'https://platzhalter-lexikon.example/ggt', 'numeric', 3),
  ((select id from lab_subcategories where key = 'liver'), 'alp', 'Alkalische Phosphatase', null, 'U/l', 'Ein Enzym aus Leber und Knochen, das bei Gallenstau oder Knochenumbau ansteigt.', 'Enzym aus Leber und Knochen; erhöht bei Gallenstau oder Knochenumbau.', 'Isoenzyme aus Leber, Knochen und Plazenta; isolierte Erhöhung erfordert Differenzierung (z. B. via GGT) zwischen cholestatischer und ossärer Ursache.', 'https://platzhalter-lexikon.example/alp', 'numeric', 4),
  ((select id from lab_subcategories where key = 'liver'), 'bilirubin_total', 'Bilirubin gesamt', null, 'mg/dl', 'Der Abbaustoff der roten Blutzellen, der bei Gelbsucht die Haut gelb färbt.', 'Abbauprodukt des roten Blutfarbstoffs; erhöht bei Leber- oder Gallenproblemen (Gelbsucht).', 'Summe aus unkonjugiertem und konjugiertem Bilirubin; Fraktionierung nötig zur Unterscheidung prähepatischer (Hämolyse), hepatischer und posthepatischer (Cholestase) Ursachen.', 'https://platzhalter-lexikon.example/bilirubin-total', 'numeric', 5),
  ((select id from lab_subcategories where key = 'liver'), 'albumin', 'Albumin', null, 'g/dl', 'Das wichtigste Eiweiß im Blut, es hält z. B. Wasser in den Blutgefäßen.', 'Wichtigstes Bluteiweiß; Hinweis auf Leberfunktion und Ernährungszustand.', 'Von der Leber synthetisiertes Transport- und onkotisches Protein; erniedrigt bei chronischer Leberinsuffizienz, Malnutrition, nephrotischem Syndrom oder chronischer Entzündung.', 'https://platzhalter-lexikon.example/albumin', 'numeric', 6),
  ((select id from lab_subcategories where key = 'kidney'), 'creatinine', 'Kreatinin', null, 'mg/dl', 'Ein Abfallstoff der Muskeln, den gesunde Nieren zuverlässig aus dem Blut filtern.', 'Abbauprodukt der Muskulatur; zentraler Marker der Nierenfunktion.', 'Muskelmassenabhängiger Filtrationsmarker; Grundlage der eGFR-Berechnung, wenig sensitiv für eine frühe Nierenfunktionseinschränkung.', 'https://platzhalter-lexikon.example/creatinine', 'numeric', 1),
  ((select id from lab_subcategories where key = 'kidney'), 'urea', 'Harnstoff', null, 'mg/dl', 'Ein weiterer Abfallstoff, der zeigt, wie gut die Nieren arbeiten.', 'Abbauprodukt des Eiweißstoffwechsels; ergänzender Nierenfunktionsmarker.', 'Endprodukt des Proteinstoffwechsels; beeinflusst durch Eiweißzufuhr, Hydratation und GI-Blutungen, daher weniger spezifisch als Kreatinin für die Nierenfunktion.', 'https://platzhalter-lexikon.example/urea', 'numeric', 2),
  ((select id from lab_subcategories where key = 'kidney'), 'egfr', 'eGFR', null, 'ml/min', 'Schätzt, wie gut deine Nieren das Blut pro Minute reinigen.', 'Geschätzte glomeruläre Filtrationsrate; zeigt die Filterleistung der Nieren.', 'Aus Kreatinin (ggf. Cystatin C), Alter und Geschlecht geschätzte Filtrationsleistung; zentrale Kenngröße zur CKD-Stadieneinteilung nach KDIGO.', 'https://platzhalter-lexikon.example/egfr', 'numeric', 3),
  ((select id from lab_subcategories where key = 'kidney'), 'uric_acid', 'Harnsäure', null, 'mg/dl', 'Ein Abbaustoff, der bei zu hohem Wert Gelenkschmerzen (Gicht) auslösen kann.', 'Abbauprodukt des Purinstoffwechsels; erhöht u. a. bei Gicht-Risiko.', 'Endprodukt des Purinstoffwechsels; Hyperurikämie erhöht das Risiko für Gichtarthritis und Uratnephropathie, oft ernährungs- und stoffwechselassoziiert.', 'https://platzhalter-lexikon.example/uric-acid', 'numeric', 4),
  ((select id from lab_subcategories where key = 'electrolytes'), 'sodium', 'Natrium', null, 'mmol/l', 'Ein Salz im Blut, das den Wasserhaushalt deines Körpers steuert.', 'Wichtigstes Elektrolyt im Blut; zentral für den Wasserhaushalt.', 'Zentraler Bestimmungsfaktor der extrazellulären Osmolalität; Dysnatriämien sind meist Ausdruck eines gestörten Wasser-, nicht primär Natriumhaushalts.', 'https://platzhalter-lexikon.example/sodium', 'numeric', 1),
  ((select id from lab_subcategories where key = 'electrolytes'), 'potassium', 'Kalium', null, 'mmol/l', 'Ein Mineralstoff, der wichtig für Herzschlag und Muskeln ist.', 'Elektrolyt; zentral für Herz- und Muskelfunktion.', 'Überwiegend intrazelluläres Kation; Dyskaliämien können akut lebensbedrohliche Herzrhythmusstörungen verursachen, daher engmaschige Kontrolle bei Abweichungen.', 'https://platzhalter-lexikon.example/potassium', 'numeric', 2),
  ((select id from lab_subcategories where key = 'electrolytes'), 'calcium', 'Calcium', null, 'mmol/l', 'Ein Mineralstoff für starke Knochen, der auch Muskeln und Nerven steuert.', 'Mineralstoff; wichtig für Knochen, Muskeln und Nervenfunktion.', 'Regulation über Parathormon und Vitamin D; Interpretation sollte das Albumin (korrigiertes Calcium) berücksichtigen, da ein relevanter Anteil proteingebunden zirkuliert.', 'https://platzhalter-lexikon.example/calcium', 'numeric', 3),
  ((select id from lab_subcategories where key = 'electrolytes'), 'chloride', 'Chlorid', null, 'mmol/l', 'Ein Salz, das zusammen mit Natrium den Säure-Basen-Haushalt ausbalanciert.', 'Elektrolyt; hält gemeinsam mit Natrium den Säure-Basen-Haushalt im Gleichgewicht.', 'Wichtigstes extrazelluläres Anion; hilfreich zur Einordnung von Säure-Basen-Störungen gemeinsam mit Bikarbonat und Anionenlücke.', 'https://platzhalter-lexikon.example/chloride', 'numeric', 4),
  ((select id from lab_subcategories where key = 'metabolism'), 'glucose', 'Glukose (nüchtern)', null, 'mg/dl', 'Der Traubenzucker im Blut, der deinem Körper Energie liefert.', 'Blutzucker (nüchtern); zentraler Marker für Diabetes-Screening.', 'Nüchternglukose als Screening-Parameter für Prädiabetes/Diabetes mellitus gemäß ADA/WHO-Grenzwerten; ergänzend HbA1c und ggf. oGTT.', 'https://platzhalter-lexikon.example/glucose', 'numeric', 1),
  ((select id from lab_subcategories where key = 'metabolism'), 'hba1c', 'HbA1c', null, '%', 'Zeigt den durchschnittlichen Blutzucker der letzten paar Monate.', '"Langzeitblutzucker"; spiegelt den durchschnittlichen Blutzucker der letzten 2-3 Monate.', 'Glykiertes Hämoglobin, spiegelt die mittlere Glukoseexposition der letzten ca. 8–12 Wochen; zentral für Diagnose und Verlaufskontrolle des Diabetes mellitus.', 'https://platzhalter-lexikon.example/hba1c', 'numeric', 2),
  ((select id from lab_subcategories where key = 'metabolism'), 'insulin', 'Insulin', null, 'µU/ml', 'Ein Hormon, das den Zucker aus dem Blut in die Zellen schleust.', 'Blutzucker-senkendes Hormon der Bauchspeicheldrüse.', 'Von Betazellen sezerniertes Hormon; gemeinsam mit der Nüchternglukose zur Beurteilung einer Insulinresistenz (z. B. HOMA-IR) nutzbar.', 'https://platzhalter-lexikon.example/insulin', 'numeric', 3),
  ((select id from lab_subcategories where key = 'lipids'), 'cholesterol_total', 'Gesamtcholesterin', null, 'mg/dl', 'Ein Fettstoff im Blut, der in "guten" und "schlechten" Formen vorkommt.', 'Gesamtcholesterin im Blut; grober Risikomarker für Herz-Kreislauf-Erkrankungen.', 'Summe aus LDL-, HDL- und VLDL-Cholesterin; als alleiniger Wert nur begrenzt aussagekräftig, das kardiovaskuläre Risiko wird über das Gesamtlipidprofil bewertet.', 'https://platzhalter-lexikon.example/cholesterol-total', 'numeric', 1),
  ((select id from lab_subcategories where key = 'lipids'), 'ldl', 'LDL-Cholesterin', null, 'mg/dl', 'Das "schlechte" Cholesterin, das sich in Blutgefäßen ablagern kann.', '"Schlechtes" Cholesterin; zentraler Risikofaktor für Arteriosklerose.', 'Zentraler kausaler Risikofaktor für Atherosklerose; Zielwerte richten sich nach dem individuellen kardiovaskulären Gesamtrisiko (z. B. SCORE2).', 'https://platzhalter-lexikon.example/ldl', 'numeric', 2),
  ((select id from lab_subcategories where key = 'lipids'), 'hdl', 'HDL-Cholesterin', null, 'mg/dl', 'Das "gute" Cholesterin, das Ablagerungen aus den Gefäßen abtransportiert.', '"Gutes" Cholesterin; schützt vor Ablagerungen in den Gefäßen.', 'Vermittelt den reversen Cholesterintransport; niedrige Werte gelten als unabhängiger kardiovaskulärer Risikofaktor, hohe Werte sind nicht per se kausal protektiv.', 'https://platzhalter-lexikon.example/hdl', 'numeric', 3),
  ((select id from lab_subcategories where key = 'lipids'), 'triglycerides', 'Triglyceride', null, 'mg/dl', 'Neutralfette im Blut, die stark von der Ernährung beeinflusst werden.', 'Neutralfette im Blut; erhöht u. a. durch Ernährung und Stoffwechselstörungen.', 'Nüchternwert empfohlen; deutlich erhöhte Werte (> 500 mg/dl) bergen zusätzlich ein Pankreatitisrisiko, oft assoziiert mit metabolischem Syndrom.', 'https://platzhalter-lexikon.example/triglycerides', 'numeric', 4),
  ((select id from lab_subcategories where key = 'iron_metabolism'), 'ferritin', 'Ferritin', null, 'ng/ml', 'Zeigt, wie viel Eisen dein Körper gespeichert hat.', 'Eisenspeicherprotein; wichtigster Marker für Eisenmangel oder -überladung.', 'Akute-Phase-Protein und Eisenspeicherparameter zugleich; kann bei Entzündung trotz Eisenmangel falsch-hoch ausfallen, ggf. gemeinsam mit CRP interpretieren.', 'https://platzhalter-lexikon.example/ferritin', 'numeric', 1),
  ((select id from lab_subcategories where key = 'iron_metabolism'), 'serum_iron', 'Serumeisen', null, 'µg/dl', 'Das Eisen, das gerade im Blut unterwegs ist – schwankt stark im Tagesverlauf.', 'Aktuell im Blut zirkulierendes Eisen; schwankt stark im Tagesverlauf.', 'Hohe intraindividuelle Tagesvariabilität; allein wenig aussagekräftig, sollte gemeinsam mit Ferritin, Transferrin und Transferrinsättigung beurteilt werden.', 'https://platzhalter-lexikon.example/serum-iron', 'numeric', 2),
  ((select id from lab_subcategories where key = 'iron_metabolism'), 'transferrin', 'Transferrin', null, 'mg/dl', 'Ein Transporter, der Eisen im Blut von einem Ort zum anderen bringt.', 'Transportprotein für Eisen im Blut.', 'Hepatisch synthetisiertes Transportprotein; steigt kompensatorisch bei Eisenmangel, sinkt bei Entzündung oder Leberinsuffizienz (negatives Akute-Phase-Protein).', 'https://platzhalter-lexikon.example/transferrin', 'numeric', 3),
  ((select id from lab_subcategories where key = 'iron_metabolism'), 'transferrin_saturation', 'Transferrinsättigung', null, '%', 'Zeigt, wie voll die Eisen-Transporter im Blut gerade beladen sind.', 'Anteil des Transferrins, der mit Eisen beladen ist; empfindlicher Eisenmangel-Marker.', 'Verhältnis von Serumeisen zur Transferrin-Bindungskapazität; sensitiver Frühindikator für funktionellen oder absoluten Eisenmangel.', 'https://platzhalter-lexikon.example/transferrin-saturation', 'numeric', 4),
  ((select id from lab_subcategories where key = 'vitamins'), 'vitamin_d', 'Vitamin D (25-OH)', null, 'ng/ml', 'Ein Vitamin, das vor allem über Sonnenlicht auf der Haut gebildet wird und für die Knochen wichtig ist.', 'Speicherform von Vitamin D; relevant für Knochen-, Immun- und Muskelfunktion.', '25-OH-Vitamin-D als Speicherform mit längster Halbwertszeit; relevant für Kalziumhomöostase, Knochenstoffwechsel und Immunmodulation.', 'https://platzhalter-lexikon.example/vitamin-d', 'numeric', 1),
  ((select id from lab_subcategories where key = 'vitamins'), 'vitamin_b12', 'Vitamin B12', null, 'pg/ml', 'Ein Vitamin, das für Nerven und Blutbildung wichtig ist – kommt vor allem in tierischen Lebensmitteln vor.', 'Wichtig für Blutbildung und Nervensystem; Mangel häufig bei veganer Ernährung.', 'Kobalamin, essenziell für DNA-Synthese und Myelinisierung; Mangel äußert sich makrozytär-hyperchrom und/oder neurologisch, die Aufnahme hängt vom Intrinsic Factor ab.', 'https://platzhalter-lexikon.example/vitamin-b12', 'numeric', 2),
  ((select id from lab_subcategories where key = 'vitamins'), 'folic_acid', 'Folsäure', null, 'ng/ml', 'Ein B-Vitamin, das wichtig für Zellteilung und Blutbildung ist.', 'B-Vitamin; wichtig für Zellteilung und Blutbildung.', 'Kofaktor der DNA-Synthese; Mangel führt zu makrozytärer Anämie, in der Schwangerschaft zusätzlich relevant für die Neuralrohrentwicklung.', 'https://platzhalter-lexikon.example/folic-acid', 'numeric', 3),
  ((select id from lab_subcategories where key = 'vitamins'), 'vitamin_b6', 'Vitamin B6', null, 'µg/l', 'Ein B-Vitamin, das beim Eiweißstoffwechsel und den Nerven hilft.', 'B-Vitamin; beteiligt am Eiweißstoffwechsel und der Nervenfunktion.', 'Kofaktor (als PLP) zahlreicher Aminosäure- und Neurotransmitter-Stoffwechselwege; Mangel selten isoliert, häufiger im Kontext allgemeiner Malnutrition.', 'https://platzhalter-lexikon.example/vitamin-b6', 'numeric', 4),
  ((select id from lab_subcategories where key = 'trace_elements'), 'zinc', 'Zink', null, 'µg/dl', 'Ein Spurenelement, das Immunsystem, Wundheilung und Haut unterstützt.', 'Spurenelement; wichtig für Immunsystem, Wundheilung und Haut.', 'Kofaktor zahlreicher Enzyme (u. a. Zink-Finger-Proteine); Mangel u. a. bei chronisch-entzündlichen Darmerkrankungen, Alkoholismus oder unausgewogener veganer Ernährung.', 'https://platzhalter-lexikon.example/zinc', 'numeric', 1),
  ((select id from lab_subcategories where key = 'trace_elements'), 'magnesium', 'Magnesium', null, 'mg/dl', 'Ein Mineralstoff, der Muskeln, Nerven und Herz unterstützt.', 'Mineralstoff; wichtig für Muskel-, Nerven- und Herzfunktion.', 'Kofaktor über 300 enzymatischer Reaktionen; Mangel begünstigt Muskelkrämpfe und Herzrhythmusstörungen, der Serumwert spiegelt die intrazellulären Speicher nur unzureichend wider.', 'https://platzhalter-lexikon.example/magnesium', 'numeric', 2),
  ((select id from lab_subcategories where key = 'trace_elements'), 'selenium', 'Selen', null, 'µg/l', 'Ein Spurenelement mit Schutzfunktion für Zellen, wichtig auch für die Schilddrüse.', 'Spurenelement mit antioxidativer Funktion; wichtig für Schilddrüse und Immunsystem.', 'Bestandteil der Selenoproteine (u. a. Glutathionperoxidasen, Dejodasen); relevant für den Schilddrüsenhormon-Metabolismus und antioxidativen Zellschutz.', 'https://platzhalter-lexikon.example/selenium', 'numeric', 3),
  ((select id from lab_subcategories where key = 'thyroid'), 'tsh', 'TSH', null, 'mU/l', 'Das Steuerhormon, das der Schilddrüse sagt, wie viel sie arbeiten soll.', 'Steuerhormon der Hirnanhangdrüse für die Schilddrüse; wichtigster Screening-Wert.', 'Hypophysäres Steuerhormon, sensitivster Screening-Parameter der Schilddrüsenfunktion; supprimiert bei Hyperthyreose, erhöht bei primärer Hypothyreose.', 'https://platzhalter-lexikon.example/tsh', 'numeric', 1),
  ((select id from lab_subcategories where key = 'thyroid'), 'ft3', 'freies T3', null, 'pg/ml', 'Das aktive Schilddrüsenhormon, das direkt im Körper wirkt.', 'Freies, aktives Schilddrüsenhormon T3.', 'Freies, biologisch aktives Trijodthyronin; v. a. relevant bei Verdacht auf T3-Hyperthyreose oder zur Verlaufskontrolle bei bekannter Schilddrüsenerkrankung.', 'https://platzhalter-lexikon.example/ft3', 'numeric', 2),
  ((select id from lab_subcategories where key = 'thyroid'), 'ft4', 'freies T4', null, 'ng/dl', 'Das andere aktive Schilddrüsenhormon, das der Körper teils in T3 umwandelt.', 'Freies, aktives Schilddrüsenhormon T4.', 'Freies Thyroxin, Hauptsekretionsprodukt der Schilddrüse und Prohormon für T3; gemeinsam mit TSH Basisdiagnostik der Schilddrüsenfunktion.', 'https://platzhalter-lexikon.example/ft4', 'numeric', 3),
  ((select id from lab_subcategories where key = 'sex_hormones'), 'testosterone', 'Testosteron', null, 'ng/dl', 'Das wichtigste männliche Geschlechtshormon, kommt auch bei Frauen in kleiner Menge vor.', 'Wichtigstes männliches Sexualhormon; auch bei Frauen in geringer Menge vorhanden.', 'Überwiegend testikulär (bzw. adrenal/ovariell) produziertes Androgen; Tagesrhythmik beachten (Morgenwert), das Gesamttestosteron kann durch die SHBG-Bindung verzerrt sein.', 'https://platzhalter-lexikon.example/testosterone', 'numeric', 1),
  ((select id from lab_subcategories where key = 'sex_hormones'), 'estradiol', 'Östradiol', null, 'pg/ml', 'Das wichtigste weibliche Geschlechtshormon, schwankt bei Frauen stark im Zyklus.', 'Wichtigstes weibliches Sexualhormon; bei Frauen stark zyklusabhängig schwankend.', 'Potentestes natürliches Östrogen; die Interpretation bei Frauen erfordert Kenntnis der Zyklusphase bzw. des Menopausenstatus.', 'https://platzhalter-lexikon.example/estradiol', 'numeric', 2),
  ((select id from lab_subcategories where key = 'sex_hormones'), 'progesterone', 'Progesteron', null, 'ng/ml', 'Ein Hormon, das nach dem Eisprung ansteigt und wichtig für eine Schwangerschaft ist.', 'Gelbkörperhormon; bei Frauen stark von der Zyklusphase abhängig.', 'Sekretionsprodukt des Corpus luteum (bzw. der Plazenta); Bestimmung meist zyklustagbezogen zur Beurteilung der Lutealphase oder Ovulation.', 'https://platzhalter-lexikon.example/progesterone', 'numeric', 3),
  ((select id from lab_subcategories where key = 'sex_hormones'), 'lh', 'LH', null, 'U/l', 'Ein Steuerhormon aus dem Gehirn, das den Eisprung bzw. die Hormonproduktion der Keimdrüsen anstößt.', 'Steuerhormon der Hirnanhangdrüse für die Keimdrüsen; bei Frauen zyklusabhängig.', 'Hypophysäres Gonadotropin; pulsatile Sekretion, bei Frauen mit charakteristischem präovulatorischem Peak, Basis der Fertilitätsdiagnostik.', 'https://platzhalter-lexikon.example/lh', 'numeric', 4),
  ((select id from lab_subcategories where key = 'sex_hormones'), 'fsh', 'FSH', null, 'U/l', 'Ein weiteres Steuerhormon aus dem Gehirn für die Eizell- bzw. Spermienreifung.', 'Steuerhormon der Hirnanhangdrüse für die Keimdrüsen; bei Frauen zyklusabhängig.', 'Hypophysäres Gonadotropin; bei Frauen zentraler Marker der ovariellen Reserve, perimenopausal ansteigend.', 'https://platzhalter-lexikon.example/fsh', 'numeric', 5),
  ((select id from lab_subcategories where key = 'adrenal'), 'cortisol', 'Cortisol', null, 'µg/dl', 'Das wichtigste Stresshormon, das morgens am höchsten ist.', 'Stresshormon der Nebenniere; folgt einem Tagesrhythmus (Morgenwert üblich).', 'Glukokortikoid mit ausgeprägter zirkadianer Rhythmik; eine Einzelmessung ist nur im Kontext der Tageszeit interpretierbar, bei Verdacht auf Dysfunktion sind dynamische Tests (z. B. Dexamethason-Hemmtest) erforderlich.', 'https://platzhalter-lexikon.example/cortisol', 'numeric', 1),
  ((select id from lab_subcategories where key = 'adrenal'), 'dhea_s', 'DHEA-S', null, 'µg/dl', 'Ein Vorstufenhormon aus der Nebenniere, das mit dem Alter abnimmt.', 'Vorstufenhormon aus der Nebenniere; nimmt mit dem Alter ab.', 'Sulfatierte Form des DHEA mit stabiler Serumkonzentration (kein Tagesrhythmus); grober Marker der adrenalen Androgenproduktion.', 'https://platzhalter-lexikon.example/dhea-s', 'numeric', 2),
  ((select id from lab_subcategories where key = 'inflammation_markers'), 'crp', 'CRP', null, 'mg/l', 'Ein Wert, der schnell ansteigt, wenn im Körper eine Entzündung aktiv ist.', 'C-reaktives Protein; unspezifischer Marker für akute Entzündungen.', 'Hepatisches Akute-Phase-Protein, Anstieg innerhalb von 6–12 h nach Entzündungsreiz; unspezifisch, aber sensitiv – hs-CRP wird zusätzlich in der kardiovaskulären Risikostratifizierung genutzt.', 'https://platzhalter-lexikon.example/crp', 'numeric', 1),
  ((select id from lab_subcategories where key = 'inflammation_markers'), 'bsg', 'Blutsenkungsgeschwindigkeit', null, 'mm/h', 'Ein älterer, langsamerer Entzündungstest.', 'Blutsenkungsgeschwindigkeit; unspezifischer, langsamer reagierender Entzündungsmarker.', 'Indirektes Maß der Erythrozytensedimentation, abhängig von Fibrinogen/Immunglobulinen; reagiert träger als CRP, ergänzend bei chronisch-entzündlichen/rheumatologischen Fragestellungen.', 'https://platzhalter-lexikon.example/bsg', 'numeric', 2),
  ((select id from lab_subcategories where key = 'inflammation_markers'), 'procalcitonin', 'Procalcitonin', null, 'ng/ml', 'Hilft zu unterscheiden, ob eine Infektion eher von Bakterien verursacht wird.', 'Marker zur Unterscheidung bakterieller von anderen Infektionen, v. a. bei Sepsis-Verdacht.', 'Steigt relativ spezifisch bei bakteriellen (v. a. systemischen) Infektionen an, im Gegensatz zu viralen Infekten; unterstützt Sepsis-Diagnostik und Antibiotikasteuerung.', 'https://platzhalter-lexikon.example/procalcitonin', 'numeric', 3),
  ((select id from lab_subcategories where key = 'cardiac_markers'), 'troponin', 'Troponin', null, 'ng/l', 'Ein Eiweiß aus dem Herzmuskel, das bei einem Herzinfarkt ansteigt.', 'Herzmuskelprotein; zentraler Marker bei Verdacht auf Herzinfarkt.', 'Hochsensitiver, kardiospezifischer Marker der Myokardnekrose; die Verlaufskinetik (Anstieg/Abfall) ist essenziell zur Abgrenzung akuter von chronischer Erhöhung.', 'https://platzhalter-lexikon.example/troponin', 'numeric', 1),
  ((select id from lab_subcategories where key = 'cardiac_markers'), 'nt_probnp', 'NT-proBNP', null, 'pg/ml', 'Ein Hormon aus dem Herzen, das bei Herzschwäche ansteigt.', 'Hormon des Herzmuskels; erhöht bei Herzschwäche (Herzinsuffizienz).', 'Vom gedehnten Myokard sezerniertes natriuretisches Peptid; Alter, Nierenfunktion und BMI beeinflussen den Wert, wichtig zur Diagnose/zum Ausschluss einer Herzinsuffizienz.', 'https://platzhalter-lexikon.example/nt-probnp', 'numeric', 2),
  ((select id from lab_subcategories where key = 'cardiac_markers'), 'ck', 'Kreatinkinase (CK)', null, 'U/l', 'Ein Enzym aus Muskeln, das bei Muskel- oder Herzschäden ansteigt.', 'Kreatinkinase; Enzym aus Herz- und Skelettmuskulatur, erhöht bei Muskel- oder Herzschäden.', 'Unspezifischer Marker der Muskelzellschädigung (Skelett- und Herzmuskel); bei kardialem Verdacht heute meist durch Troponin abgelöst, weiterhin relevant für Myopathien/Rhabdomyolyse.', 'https://platzhalter-lexikon.example/ck', 'numeric', 3),
  ((select id from lab_subcategories where key = 'tumor_markers'), 'psa', 'PSA', null, 'ng/ml', 'Ein Wert aus der Prostata, der zur Verlaufskontrolle genutzt wird, aber kein alleiniger Krebsbeweis ist.', 'Prostataspezifisches Antigen; Verlaufs- und Vorsorgemarker der Prostata, kein alleiniger Krebsbeweis.', 'Organspezifisch, nicht tumorspezifisch; auch bei benigner Prostatahyperplasie oder Prostatitis erhöht, der Verlauf/die Kinetik (PSA-Velocity) ist oft aussagekräftiger als der Einzelwert.', 'https://platzhalter-lexikon.example/psa', 'numeric', 1),
  ((select id from lab_subcategories where key = 'tumor_markers'), 'ca_125', 'CA-125', null, 'U/ml', 'Ein Wert, der vor allem zur Verlaufskontrolle bei bestimmten Erkrankungen des Bauchraums genutzt wird.', 'Tumormarker, v. a. zur Verlaufskontrolle bei Eierstockkrebs; auch bei gutartigen Erkrankungen erhöht.', 'Wenig spezifischer Tumormarker; auch bei Endometriose, Menstruation oder Peritonealreizung erhöht, primär zur Verlaufsbeurteilung bei bekanntem Ovarialkarzinom geeignet.', 'https://platzhalter-lexikon.example/ca-125', 'numeric', 2),
  ((select id from lab_subcategories where key = 'tumor_markers'), 'cea', 'CEA', null, 'ng/ml', 'Ein unspezifischer Marker, der vor allem bei der Nachsorge von Darmkrebs genutzt wird.', 'Unspezifischer Tumormarker, v. a. zur Verlaufskontrolle bei Darmkrebs; bei Rauchern oft erhöht.', 'Nicht zum Screening geeignet; bei Rauchern sowie diversen benignen Erkrankungen erhöht, primäre Bedeutung in der postoperativen Verlaufskontrolle kolorektaler Karzinome.', 'https://platzhalter-lexikon.example/cea', 'numeric', 3),
  ((select id from lab_subcategories where key = 'tumor_markers'), 'afp', 'AFP', null, 'ng/ml', 'Ein Marker, der vor allem bei Leberkrebs verfolgt wird und in der Schwangerschaft natürlich erhöht ist.', 'Tumormarker, v. a. zur Verlaufskontrolle bei Leberkrebs; in der Schwangerschaft physiologisch erhöht.', 'Physiologisch erhöht in der Fetalperiode und Schwangerschaft; bei Erwachsenen v. a. relevant zur Verlaufskontrolle des hepatozellulären Karzinoms und bei Keimzelltumoren.', 'https://platzhalter-lexikon.example/afp', 'numeric', 4),
  ((select id from lab_subcategories where key = 'serology'), 'hiv', 'HIV', null, null, 'Ein Test, der prüft, ob eine HIV-Infektion vorliegt.', 'Antikörper-/Antigentest auf eine HIV-Infektion.', 'Kombinierter Antikörper-/p24-Antigen-Test (4. Generation); reaktive Befunde erfordern eine Bestätigungstestung, das diagnostische Fenster nach Exposition ist zu beachten.', 'https://platzhalter-lexikon.example/hiv', 'qualitative', 1),
  ((select id from lab_subcategories where key = 'serology'), 'hepatitis_b', 'Hepatitis B', null, null, 'Ein Test, der prüft, ob eine Hepatitis-B-Infektion vorliegt oder vorlag.', 'Serologischer Nachweis einer akuten oder durchgemachten Hepatitis-B-Infektion.', 'Serologisches Panel (u. a. HBsAg, Anti-HBc, Anti-HBs) unterscheidet akute/chronische Infektion, durchgemachte Infektion und Impfschutz.', 'https://platzhalter-lexikon.example/hepatitis-b', 'qualitative', 2),
  ((select id from lab_subcategories where key = 'serology'), 'hepatitis_c', 'Hepatitis C', null, null, 'Ein Test, der prüft, ob eine Hepatitis-C-Infektion vorliegt oder vorlag.', 'Serologischer Nachweis einer Hepatitis-C-Infektion.', 'Anti-HCV-Antikörpertest als Screening; ein reaktiver Befund erfordert eine HCV-RNA-Bestätigung zur Unterscheidung zwischen ausgeheilter und aktiver Infektion.', 'https://platzhalter-lexikon.example/hepatitis-c', 'qualitative', 3),
  ((select id from lab_subcategories where key = 'autoimmune_markers'), 'ana', 'Antinukleäre Antikörper (ANA)', null, null, 'Ein Screening-Test auf Antikörper, die den eigenen Körper angreifen können.', 'Antinukleäre Antikörper; Screening-Marker für Autoimmunerkrankungen wie Lupus.', 'Screening-Marker für systemische Autoimmunerkrankungen (u. a. Lupus); niedrigtitrige positive Befunde sind auch bei Gesunden möglich, positive Befunde erfordern Titer- und Musteranalyse plus Subtyp-Antikörper.', 'https://platzhalter-lexikon.example/ana', 'qualitative', 1),
  ((select id from lab_subcategories where key = 'autoimmune_markers'), 'rheumatoid_factor', 'Rheumafaktor', null, 'IU/ml', 'Ein Antikörper, der bei rheumatischen Gelenkerkrankungen oft erhöht ist.', 'Antikörper, die bei rheumatoider Arthritis häufig erhöht sind.', 'Autoantikörper gegen das Fc-Fragment von IgG; mäßige Sensitivität/Spezifität für rheumatoide Arthritis, auch bei anderen Erkrankungen oder Gesunden positiv möglich.', 'https://platzhalter-lexikon.example/rheumatoid-factor', 'numeric', 2),
  ((select id from lab_subcategories where key = 'autoimmune_markers'), 'anti_ccp', 'Anti-CCP', null, 'U/ml', 'Ein spezifischerer Antikörper-Test für rheumatische Gelenkerkrankungen.', 'Spezifischer Antikörper-Marker für rheumatoide Arthritis.', 'Antikörper gegen citrullinierte Peptide; höhere Spezifität als der Rheumafaktor für rheumatoide Arthritis, kann Jahre vor Symptombeginn positiv sein.', 'https://platzhalter-lexikon.example/anti-ccp', 'numeric', 3),
  ((select id from lab_subcategories where key = 'allergy_general'), 'ige_total', 'Gesamt-IgE', null, 'kU/l', 'Die Gesamtmenge eines Antikörpertyps, der bei Allergien eine Rolle spielt.', 'Gesamtmenge des Antikörpertyps IgE im Blut; allgemeiner Hinweis auf allergische Neigung.', 'Unspezifischer Marker der atopischen Gesamtdisposition; auch bei Parasitosen erhöht, für sich genommen nicht diagnostisch – spezifisches IgE ist aussagekräftiger.', 'https://platzhalter-lexikon.example/ige-total', 'numeric', 1),
  ((select id from lab_subcategories where key = 'allergy_general'), 'tryptase', 'Tryptase', null, 'µg/l', 'Ein Wert, der bei starken allergischen Reaktionen stark ansteigt.', 'Mastzell-Marker; erhöht u. a. bei schweren allergischen Reaktionen (Anaphylaxie).', 'Mastzell-spezifisches Enzym; ein akuter Anstieg (Bestimmung 1–4 h nach dem Ereignis) stützt die Diagnose Anaphylaxie, dauerhaft erhöhte Basalwerte können auf eine Mastzellerkrankung hinweisen.', 'https://platzhalter-lexikon.example/tryptase', 'numeric', 2),
  ((select id from lab_subcategories where key = 'allergy_general'), 'ecp', 'Eosinophiles kationisches Protein (ECP)', null, 'µg/l', 'Zeigt, wie aktiv die allergische Entzündung gerade ist.', 'Eosinophiles kationisches Protein; Marker für allergische Entzündungsaktivität.', 'Freigesetzt aus aktivierten Eosinophilen; Marker der eosinophilen Entzündungsaktivität, u. a. zur Verlaufsbeurteilung bei Asthma/Atopie genutzt, wenig standardisiert.', 'https://platzhalter-lexikon.example/ecp', 'numeric', 3),
  ((select id from lab_subcategories where key = 'allergy_general'), 'basophil_activation_test', 'Basophilen-Aktivierungstest (BAT)', null, '%', 'Ein Zelltest, der zeigt, wie stark bestimmte Abwehrzellen auf ein Allergen reagieren.', 'Zelltest, misst die Aktivierbarkeit basophiler Zellen durch ein Allergen.', 'Durchflusszytometrischer Funktionstest der basophilen Aktivierbarkeit; ergänzt spezifisches IgE u. a. bei diskrepanten Befunden oder Verdacht auf Nahrungsmittel-/Medikamentenallergie.', 'https://platzhalter-lexikon.example/basophil-activation-test', 'numeric', 4),
  ((select id from lab_subcategories where key = 'allergy_inhalant'), 'ige_grass_pollen', 'Gräserpollen', null, 'kU/l', 'Zeigt, ob dein Immunsystem allergisch auf Gräserpollen reagiert.', 'Spezifischer IgE-Antikörper gegen Gräserpollen; Nachweis einer allergischen Sensibilisierung.', 'Spezifischer IgE-Nachweis gegen Gräserpollen; ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.', 'https://platzhalter-lexikon.example/ige-grass-pollen', 'numeric', 1),
  ((select id from lab_subcategories where key = 'allergy_inhalant'), 'ige_rye_pollen', 'Roggenpollen', null, 'kU/l', 'Zeigt, ob dein Immunsystem allergisch auf Roggenpollen reagiert.', 'Spezifischer IgE-Antikörper gegen Roggenpollen; Nachweis einer allergischen Sensibilisierung.', 'Spezifischer IgE-Nachweis gegen Roggenpollen; ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.', 'https://platzhalter-lexikon.example/ige-rye-pollen', 'numeric', 2),
  ((select id from lab_subcategories where key = 'allergy_inhalant'), 'ige_birch_pollen', 'Birkenpollen', null, 'kU/l', 'Zeigt, ob dein Immunsystem allergisch auf Birkenpollen reagiert.', 'Spezifischer IgE-Antikörper gegen Birkenpollen; Nachweis einer allergischen Sensibilisierung.', 'Spezifischer IgE-Nachweis gegen Birkenpollen; ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.', 'https://platzhalter-lexikon.example/ige-birch-pollen', 'numeric', 3),
