  ((select id from lab_subcategories where key = 'allergy_food'), 'ige_fish', 'Fisch', null, 'kU/l', 'Zeigt, ob dein Immunsystem allergisch auf Fisch reagiert.', 'Spezifischer IgE-Antikörper gegen Fisch; Nachweis einer allergischen Sensibilisierung.', 'Spezifischer IgE-Nachweis gegen Fisch; ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.', 'https://platzhalter-lexikon.example/ige-fish', 'numeric', 9),
  ((select id from lab_subcategories where key = 'allergy_food'), 'ige_shellfish', 'Krebstiere/Schalentiere', null, 'kU/l', 'Zeigt, ob dein Immunsystem allergisch auf Krebs- und Schalentiere reagiert.', 'Spezifischer IgE-Antikörper gegen Krebs- und Schalentiere; Nachweis einer allergischen Sensibilisierung.', 'Spezifischer IgE-Nachweis gegen Krebs- und Schalentiere; ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.', 'https://platzhalter-lexikon.example/ige-shellfish', 'numeric', 10),
  ((select id from lab_subcategories where key = 'allergy_food'), 'ige_celery', 'Sellerie', null, 'kU/l', 'Zeigt, ob dein Immunsystem allergisch auf Sellerie reagiert.', 'Spezifischer IgE-Antikörper gegen Sellerie; Nachweis einer allergischen Sensibilisierung.', 'Spezifischer IgE-Nachweis gegen Sellerie; ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.', 'https://platzhalter-lexikon.example/ige-celery', 'numeric', 11),
  ((select id from lab_subcategories where key = 'allergy_food'), 'ige_sesame', 'Sesam', null, 'kU/l', 'Zeigt, ob dein Immunsystem allergisch auf Sesam reagiert.', 'Spezifischer IgE-Antikörper gegen Sesam; Nachweis einer allergischen Sensibilisierung.', 'Spezifischer IgE-Nachweis gegen Sesam; ein positiver Wert zeigt eine Sensibilisierung, nicht zwingend eine klinisch relevante Allergie – muss immer mit den Symptomen abgeglichen werden.', 'https://platzhalter-lexikon.example/ige-sesame', 'numeric', 12),
  ((select id from lab_subcategories where key = 'allergy_venom'), 'ige_wasp_venom', 'Wespengift', null, 'kU/l', 'Zeigt, ob dein Immunsystem allergisch auf Wespengift reagiert.', 'Spezifischer IgE-Antikörper gegen Wespengift; Nachweis einer allergischen Sensibilisierung.', 'Spezifischer IgE-Nachweis gegen Wespengift; bei Insektengiftallergie zusätzlich relevant für die Einschätzung des Anaphylaxierisikos und eine mögliche Hyposensibilisierung.', 'https://platzhalter-lexikon.example/ige-wasp-venom', 'numeric', 1),
  ((select id from lab_subcategories where key = 'allergy_venom'), 'ige_bee_venom', 'Bienengift', null, 'kU/l', 'Zeigt, ob dein Immunsystem allergisch auf Bienengift reagiert.', 'Spezifischer IgE-Antikörper gegen Bienengift; Nachweis einer allergischen Sensibilisierung.', 'Spezifischer IgE-Nachweis gegen Bienengift; bei Insektengiftallergie zusätzlich relevant für die Einschätzung des Anaphylaxierisikos und eine mögliche Hyposensibilisierung.', 'https://platzhalter-lexikon.example/ige-bee-venom', 'numeric', 2),
  ((select id from lab_subcategories where key = 'allergy_molecular'), 'ige_bet_v_1', 'Bet v 1 (Birke, Hauptallergen)', null, 'kU/l', 'Prüft speziell auf das Hauptallergen der Birke, um eine echte Birkenpollenallergie von einer Kreuzreaktion zu unterscheiden.', 'Hauptallergen-Komponente der Birke; unterscheidet echte Birkenallergie von Kreuzreaktionen.', 'Komponentenaufgelöste Diagnostik (CRD) für das Majorallergen Bet v 1; hilft, eine genuine Birkensensibilisierung von einer profilin-/PR-10-vermittelten Kreuzreaktivität (z. B. mit Nahrungsmitteln) abzugrenzen.', 'https://platzhalter-lexikon.example/ige-bet-v-1', 'numeric', 1),
  ((select id from lab_subcategories where key = 'allergy_molecular'), 'ige_ara_h_2', 'Ara h 2 (Erdnuss, Hauptallergen)', null, 'kU/l', 'Prüft ein Erdnuss-Eiweiß, das auf ein höheres Risiko für starke Reaktionen hinweisen kann.', 'Hauptallergen-Komponente der Erdnuss; Hinweis auf ein höheres Risiko schwerer Reaktionen.', 'Speicherprotein-Komponente mit hoher Assoziation zu schweren, systemischen Reaktionen; hilfreich zur Risikoeinschätzung bei Erdnusssensibilisierung.', 'https://platzhalter-lexikon.example/ige-ara-h-2', 'numeric', 2),
  ((select id from lab_subcategories where key = 'allergy_molecular'), 'ige_phl_p_1', 'Phl p 1 (Gräser, Hauptallergen)', null, 'kU/l', 'Prüft das Hauptallergen der Gräser, um eine echte Gräserallergie von einer Kreuzreaktion zu unterscheiden.', 'Hauptallergen-Komponente der Gräser; unterscheidet echte Gräserallergie von Kreuzreaktionen.', 'Majorallergen-Komponente der Süßgräser; unterstützt die Unterscheidung einer genuinen Gräserpollenallergie von polysensibilisierten Kreuzreaktionsmustern.', 'https://platzhalter-lexikon.example/ige-phl-p-1', 'numeric', 3),
  ((select id from lab_subcategories where key = 'allergy_skin_tests'), 'skin_prick_test', 'Pricktest', null, 'mm (Quaddelgröße)', 'Ein Allergietest, bei dem ein Tropfen Allergenlösung auf die Haut kommt und leicht angeritzt wird.', 'Hauttest: Allergen wird in die Haut eingebracht, Quaddelgröße nach ca. 15-20 Min. abgelesen.', 'In-vivo-Sofortreaktionstest; die Quaddelgröße nach 15–20 Min. korreliert mit dem Sensibilisierungsgrad, muss stets mit der Anamnese abgeglichen werden.', 'https://platzhalter-lexikon.example/skin-prick-test', 'numeric', 1),
  ((select id from lab_subcategories where key = 'allergy_skin_tests'), 'intracutaneous_test', 'Intrakutantest', null, 'mm (Quaddelgröße)', 'Ein empfindlicherer Allergietest, bei dem das Allergen unter die Haut gespritzt wird.', 'Empfindlicherer Hauttest als der Pricktest; Allergen wird in die Haut injiziert.', 'Höhere Sensitivität, aber geringere Spezifität als der Pricktest; v. a. bei unklarem Pricktest oder in der Insektengiftallergie-Diagnostik eingesetzt.', 'https://platzhalter-lexikon.example/intracutaneous-test', 'numeric', 2),
  ((select id from lab_subcategories where key = 'allergy_skin_tests'), 'patch_test', 'Epikutantest / Patchtest', null, null, 'Ein Test für Kontaktallergien, bei dem Pflaster mit Testsubstanzen mehrere Tage auf der Haut bleiben.', 'Epikutantest zum Nachweis von Kontaktallergien; Ablesung nach 48-72 Stunden.', 'Prüft eine T-Zell-vermittelte Typ-IV-Reaktion (Spättyp); Ablesung nach 48 und 72 h, Standard zur Abklärung von Kontaktekzemen.', 'https://platzhalter-lexikon.example/patch-test', 'qualitative', 3),
  ((select id from lab_subcategories where key = 'allergy_provocation'), 'nasal_provocation', 'Nasale Provokation', null, null, 'Das Allergen wird gezielt in die Nase gegeben, um eine Allergie zu bestätigen.', 'Gezielte Allergen-Gabe auf die Nasenschleimhaut zur Bestätigung einer Allergie.', 'In-vivo-Provokationstest bei diskrepanten Ergebnissen von Anamnese, Haut- und IgE-Test; nahezu Goldstandard-Methode für die allergische Rhinitis.', 'https://platzhalter-lexikon.example/nasal-provocation', 'qualitative', 1),
  ((select id from lab_subcategories where key = 'allergy_provocation'), 'bronchial_provocation', 'Bronchiale Provokation', null, null, 'Das Allergen wird gezielt eingeatmet, um zu prüfen, ob die Atemwege allergisch reagieren.', 'Gezielte Allergen-Gabe zur Prüfung einer allergischen Atemwegsreaktion.', 'Provokation zur Objektivierung einer allergischen Atemwegsreaktion; wird unter kontrollierten Bedingungen mit Lungenfunktionsmonitoring durchgeführt, u. a. bei der Abklärung von Berufsasthma.', 'https://platzhalter-lexikon.example/bronchial-provocation', 'qualitative', 2),
  ((select id from lab_subcategories where key = 'allergy_provocation'), 'oral_food_challenge', 'Orale Nahrungsmittelprovokation', null, null, 'Ein Nahrungsmittel wird unter ärztlicher Aufsicht gegessen, um eine Allergie sicher zu bestätigen oder auszuschließen.', 'Kontrollierte orale Gabe eines Nahrungsmittels zur Bestätigung oder zum Ausschluss einer Allergie.', 'Goldstandard der Nahrungsmittelallergie-Diagnostik; titrierte, ärztlich überwachte Verabreichung (idealerweise doppelblind-plazebokontrolliert) zur definitiven Diagnosesicherung.', 'https://platzhalter-lexikon.example/oral-food-challenge', 'qualitative', 3),
  ((select id from lab_subcategories where key = 'urine_status'), 'urine_ph', 'pH-Wert', null, null, 'Zeigt, wie sauer oder basisch dein Urin gerade ist.', 'Säuregrad des Urins; beeinflusst u. a. durch Ernährung und Infektionen.', 'Beeinflusst durch Ernährung, Stoffwechsellage und Infektionen; z. B. alkalischer pH bei ureasebildenden Harnwegsinfekt-Erregern.', 'https://platzhalter-lexikon.example/urine-ph', 'numeric', 1),
  ((select id from lab_subcategories where key = 'urine_status'), 'urine_specific_gravity', 'Spezifisches Gewicht', null, 'g/ml', 'Zeigt, wie konzentriert dein Urin gerade ist – hängt stark davon ab, wie viel du getrunken hast.', 'Spezifisches Gewicht des Urins; Hinweis auf die Konzentrationsfähigkeit der Nieren.', 'Grobes Maß der renalen Konzentrationsfähigkeit; niedrige Werte bei hoher Flüssigkeitszufuhr oder Diabetes insipidus, hohe Werte bei Dehydratation.', 'https://platzhalter-lexikon.example/urine-specific-gravity', 'numeric', 2),
  ((select id from lab_subcategories where key = 'urine_status'), 'urine_protein', 'Protein', null, 'mg/dl', 'Zeigt, ob Eiweiß über den Urin ausgeschieden wird, was ein früher Hinweis auf die Nieren sein kann.', 'Eiweißausscheidung im Urin; erhöht als früher Hinweis auf Nierenschäden.', 'Semiquantitativer Streifentest, v. a. sensitiv für Albumin; positive Befunde erfordern Bestätigung/Quantifizierung (z. B. Albumin-Kreatinin-Ratio).', 'https://platzhalter-lexikon.example/urine-protein', 'numeric', 3),
  ((select id from lab_subcategories where key = 'urine_status'), 'urine_glucose', 'Glukose', null, 'mg/dl', 'Zeigt Zucker im Urin, was meist erst bei sehr hohem Blutzucker vorkommt.', 'Zuckerausscheidung im Urin; normalerweise nur bei stark erhöhtem Blutzucker nachweisbar.', 'Tritt auf, wenn die renale Reabsorptionskapazität (Nierenschwelle) überschritten wird; klassisch bei unzureichend eingestelltem Diabetes mellitus.', 'https://platzhalter-lexikon.example/urine-glucose', 'numeric', 4),
  ((select id from lab_subcategories where key = 'urine_status'), 'urine_ketones', 'Ketone', null, 'mg/dl', 'Zeigt Abbauprodukte aus dem Fettstoffwechsel im Urin, z. B. beim Fasten oder bei wenig Kohlenhydraten.', 'Ketonkörper im Urin; Hinweis auf Fettstoffwechsel bei Fasten, Diabetes oder kohlenhydratarmer Ernährung.', 'Hinweis auf gesteigerte Lipolyse/Ketogenese; relevant zur Erkennung einer diabetischen Ketoazidose, auch physiologisch bei Fasten oder Low-Carb-Ernährung.', 'https://platzhalter-lexikon.example/urine-ketones', 'numeric', 5),
  ((select id from lab_subcategories where key = 'urine_status'), 'urine_nitrite', 'Nitrit', null, null, 'Zeigt Bakterien im Urin an, die typisch für eine Blasenentzündung sind.', 'Hinweis auf bestimmte Bakterien im Urin, typisch bei Harnwegsinfekten.', 'Nitrit entsteht durch bakterielle Reduktion von Nitrat; positiv v. a. bei Enterobacteriaceae, ein negativer Befund schließt einen HWI aber nicht sicher aus.', 'https://platzhalter-lexikon.example/urine-nitrite', 'qualitative', 6),
  ((select id from lab_subcategories where key = 'urine_status'), 'urine_leukocytes', 'Leukozyten', null, 'Leu/µl', 'Weiße Blutzellen im Urin, die auf eine Entzündung der Harnwege hinweisen.', 'Weiße Blutkörperchen im Urin; erhöht bei Harnwegsinfekten.', 'Leukozyturie als Hinweis auf ein entzündliches Geschehen der Harnwege; im Kontext von Nitrit und Klinik zur HWI-Diagnostik zu interpretieren.', 'https://platzhalter-lexikon.example/urine-leukocytes', 'numeric', 7),
  ((select id from lab_subcategories where key = 'urine_status'), 'urine_blood', 'Blut (Erythrozyten)', null, 'Ery/µl', 'Rote Blutzellen im Urin, z. B. durch eine Infektion, Steine oder andere Ursachen.', 'Rote Blutkörperchen im Urin; Hinweis u. a. auf Infekte, Steine oder Nierenerkrankungen.', 'Mikro-/Makrohämaturie erfordert eine Abklärung der Quelle (glomerulär vs. postrenal); persistierende asymptomatische Hämaturie bedarf weiterführender Diagnostik.', 'https://platzhalter-lexikon.example/urine-blood', 'numeric', 8),
  ((select id from lab_subcategories where key = 'kidney_early_detection'), 'urine_microalbumin', 'Mikroalbumin', null, 'mg/l', 'Prüft kleinste Eiweißmengen im Urin, die sehr früh auf beginnende Nierenschäden hinweisen können, z. B. bei Diabetes.', 'Kleinste Mengen Eiweiß im Urin; sehr früher Marker für beginnende Nierenschäden, u. a. bei Diabetes.', 'Sensitivster Frühmarker der diabetischen/hypertensiven Nephropathie; Beurteilung idealerweise über die Albumin-Kreatinin-Ratio im Spontanurin.', 'https://platzhalter-lexikon.example/urine-microalbumin', 'numeric', 1),
  ((select id from lab_subcategories where key = 'kidney_early_detection'), 'creatinine_clearance', 'Kreatinin-Clearance (24h-Sammelurin)', null, 'ml/min', 'Misst über gesammelten Urin, wie gut die Nieren Abfallstoffe herausfiltern.', 'Misst über Sammelurin, wie viel Blut die Nieren pro Minute von Kreatinin reinigen.', 'Funktionelle GFR-Schätzung über 24-h-Sammelurin; anfällig für Sammelfehler, wird zunehmend durch die formelbasierte eGFR ersetzt, bleibt aber bei extremen Körpermaßen relevant.', 'https://platzhalter-lexikon.example/creatinine-clearance', 'numeric', 2),
  ((select id from lab_subcategories where key = 'urine_culture'), 'urine_culture_result', 'Urinkultur (Erregernachweis)', null, null, 'Ein Labortest, der prüft, ob und welche Bakterien im Urin wachsen.', 'Bakteriologischer Nachweis; bestätigt oder schließt einen Harnwegsinfekt aus.', 'Quantitative bakteriologische Kultur mit Keimzahlbestimmung und Erregeridentifikation; Grundlage für Antibiogramm und gezielte Antibiotikatherapie bei HWI.', 'https://platzhalter-lexikon.example/urine-culture-result', 'qualitative', 1),
  ((select id from lab_subcategories where key = 'urine_drug_screening'), 'urine_drug_screen', 'Drogenscreening im Urin', null, null, 'Ein Schnelltest, der auf Rückstände bestimmter Substanzen im Urin prüft.', 'Schnelltest auf gängige Drogen- bzw. Medikamentenrückstände im Urin.', 'Immunologischer Schnelltest mit Cutoff-Werten; positive Befunde sind bei forensischer/arbeitsmedizinischer Relevanz durch Bestätigungsanalytik (z. B. GC-MS) zu verifizieren.', 'https://platzhalter-lexikon.example/urine-drug-screen', 'qualitative', 1),
  ((select id from lab_subcategories where key = 'colorectal_screening'), 'occult_blood', 'Occultes Blut (Hämoccult-Test)', null, null, 'Ein Test, der nicht sichtbares Blut im Stuhl nachweist – ein früher Hinweis, den man ernst nehmen sollte.', 'Nachweis von nicht sichtbarem Blut im Stuhl; Screening-Marker u. a. für Darmkrebs.', 'Immunologischer fäkaler Okkultbluttest (iFOBT); etabliertes Screening-Instrument für kolorektale Karzinome/Polypen, ein positiver Befund erfordert eine Koloskopie.', 'https://platzhalter-lexikon.example/occult-blood', 'qualitative', 1),
  ((select id from lab_subcategories where key = 'stool_inflammation_markers'), 'calprotectin', 'Calprotectin', null, 'µg/g', 'Ein Wert im Stuhl, der zeigt, ob im Darm gerade eine Entzündung aktiv ist.', 'Entzündungsmarker im Stuhl; unterscheidet entzündliche von funktionellen Darmerkrankungen.', 'Neutrophilen-assoziiertes Protein; hilft, entzündliche Darmerkrankungen (CED) von funktionellen Beschwerden wie dem Reizdarmsyndrom zu unterscheiden.', 'https://platzhalter-lexikon.example/calprotectin', 'numeric', 1),
  ((select id from lab_subcategories where key = 'stool_infection_diagnostics'), 'helicobacter_pylori_antigen', 'Helicobacter-pylori-Antigen', null, null, 'Ein Test, der prüft, ob ein bestimmtes Magenbakterium vorhanden ist.', 'Nachweis des magenschleimhautbesiedelnden Bakteriums H. pylori im Stuhl.', 'Nicht-invasiver Nachweis von H.-pylori-Antigen im Stuhl; hohe Sensitivität/Spezifität, geeignet zur Erst- und Eradikationskontrolle (PPI-Pause vor Testung beachten).', 'https://platzhalter-lexikon.example/helicobacter-pylori-antigen', 'qualitative', 1),
  ((select id from lab_subcategories where key = 'stool_infection_diagnostics'), 'parasites_worm_eggs', 'Parasiten/Wurmeier', null, null, 'Eine mikroskopische Untersuchung auf Darmparasiten oder deren Eier.', 'Mikroskopischer Nachweis von Darmparasiten oder deren Eiern im Stuhl.', 'Mikroskopischer Nachweis von Parasiten/Eiern; aufgrund intermittierender Ausscheidung ggf. Untersuchung mehrerer Proben an unterschiedlichen Tagen sinnvoll.', 'https://platzhalter-lexikon.example/parasites-worm-eggs', 'qualitative', 2),
  ((select id from lab_subcategories where key = 'microbiome'), 'microbiome_analysis', 'Darmflora-Zusammensetzung', null, null, 'Beschreibt, welche Bakterien in deinem Darm leben und wie vielfältig sie sind.', 'Beschreibt die Zusammensetzung der Darmbakterien; Befund als Text, kein einfacher Grenzwert.', 'Sequenzierungsbasierte Zusammensetzungsanalyse der Darmmikrobiota; klinische Interpretierbarkeit und Standardisierung derzeit limitiert, der Befund ist meist deskriptiv ohne etablierte Referenzbereiche.', 'https://platzhalter-lexikon.example/microbiome-analysis', 'qualitative', 1);
